coding_problems.solution_sql:
SELECT announcement_id, title FROM announcements
WHERE published = 1 -- Drafts do not belong in the published report.
ORDER BY announcement_id;

/* Match recorded title text exactly; marker-like characters inside strings remain data. */
SELECT audience, COUNT(*) AS marked_count FROM announcements
WHERE published = 1 AND (CAST(title AS BINARY) = 'priority -- review' OR CAST(title AS BINARY) = 'review /* pending */')
GROUP BY audience ORDER BY audience;
